import { NextResponse } from 'next/server';

let certificates = [
    { id: 536179, protocol: '20260129-977E', holder: 'Lutero E Associados', product: 'e-CNPJ A1 - 1 Ano', seller: 'Maria Silva', status: 'Pendente', statusColor: 'amber', date: '2026-01-29', doc: '12.345.678/0001-90' },
    { id: 536180, protocol: '20260129-45D1', holder: 'Montenegro E Duarte', product: 'e-CPF A3 - 3 Anos', seller: 'Maria Silva', status: 'Pago', statusColor: 'emerald', date: '2026-01-29', doc: '123.456.789-00' },
    { id: 535900, protocol: '20260120-A2B3', holder: 'Verdugo E Rios', product: 'e-CPF A1', seller: 'Externo B', status: 'Cancelado', statusColor: 'rose', date: '2026-01-20', doc: '987.654.321-11' }
];

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const seller = searchParams.get('seller');

    let filtered = certificates;
    if (seller && seller !== 'admin') {
        filtered = certificates.filter(c => c.seller === seller);
    }

    return NextResponse.json(filtered);
}
